using System.Security.Claims;
using System.Security.Cryptography;
using EduForge.Domain;
using EduForge.Infrastructure;
using Microsoft.EntityFrameworkCore;
namespace EduForge.Api;
public record EnrollmentInput(string FirstName,string LastName);
public static class InvitationEndpoints{
 static Guid Owner(ClaimsPrincipal user)=>Guid.Parse(user.FindFirstValue(ClaimTypes.NameIdentifier)!);
 public static void MapInvitations(this WebApplication app){
 var own=app.MapGroup("/api/groups/{id:guid}/invitation").RequireAuthorization();
 own.MapGet("/",async(Guid id,ClaimsPrincipal user,MaterialDbContext db,CancellationToken ct)=>{if(!await db.Groups.AnyAsync(x=>x.Id==id&&x.TeacherId==Owner(user),ct))return Results.NotFound();return Results.Ok(new{invitation=await db.Invitations.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id,ct),requests=await db.Enrollments.AsNoTracking().Where(x=>x.GroupId==id&&x.Status=="Pending").OrderBy(x=>x.LastName).ToListAsync(ct)});});
 own.MapPost("/",async(Guid id,ClaimsPrincipal user,MaterialDbContext db,CancellationToken ct)=>{if(!await db.Groups.AnyAsync(x=>x.Id==id&&x.TeacherId==Owner(user),ct))return Results.NotFound();var invitation=await db.Invitations.SingleOrDefaultAsync(x=>x.Id==id,ct);if(invitation is null){invitation=new GroupInvitation{Id=id};db.Invitations.Add(invitation);}invitation.Token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32));invitation.Enabled=true;await db.SaveChangesAsync(ct);return Results.Ok(invitation);});
 own.MapDelete("/",async(Guid id,ClaimsPrincipal user,MaterialDbContext db,CancellationToken ct)=>{if(!await db.Groups.AnyAsync(x=>x.Id==id&&x.TeacherId==Owner(user),ct))return Results.NotFound();await db.Invitations.Where(x=>x.Id==id).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.Enabled,false),ct);return Results.NoContent();});
 own.MapPost("/requests/{requestId:guid}/{decision}",async(Guid id,Guid requestId,string decision,ClaimsPrincipal user,MaterialDbContext db,CancellationToken ct)=>{if(decision is not("approve" or "reject"))return Results.BadRequest();if(!await db.Groups.AnyAsync(x=>x.Id==id&&x.TeacherId==Owner(user),ct))return Results.NotFound();await using var transaction=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);var request=await db.Enrollments.SingleOrDefaultAsync(x=>x.Id==requestId&&x.GroupId==id&&x.Status=="Pending",ct);if(request is null)return Results.NotFound();if(decision=="approve"){if(await db.Students.CountAsync(x=>x.GroupId==id,ct)>=200)return Results.Conflict(new{message="В группе уже 200 студентов."});var duplicate=await db.Students.AnyAsync(x=>x.GroupId==id&&x.FirstName==request.FirstName&&x.LastName==request.LastName,ct);if(!duplicate)db.Students.Add(new Student{GroupId=id,FirstName=request.FirstName,LastName=request.LastName});request.Status="Approved";}else request.Status="Rejected";await db.SaveChangesAsync(ct);await transaction.CommitAsync(ct);return Results.NoContent();});
 app.MapGet("/api/enroll/{token}",async(string token,MaterialDbContext db,CancellationToken ct)=>{var invitation=await db.Invitations.AsNoTracking().SingleOrDefaultAsync(x=>x.Token==token&&x.Enabled,ct);if(invitation is null)return Results.NotFound();return Results.Ok(new{name=await db.Groups.Where(x=>x.Id==invitation.Id).Select(x=>x.Name).SingleAsync(ct)});}).RequireRateLimiting("join");
 app.MapPost("/api/enroll/{token}",async(string token,EnrollmentInput input,MaterialDbContext db,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(input.FirstName)||string.IsNullOrWhiteSpace(input.LastName)||input.FirstName.Length>100||input.LastName.Length>100)return Results.BadRequest(new{message="Введите имя и фамилию, до 100 символов."});var invitation=await db.Invitations.AsNoTracking().SingleOrDefaultAsync(x=>x.Token==token&&x.Enabled,ct);if(invitation is null)return Results.NotFound();var name=$"{input.FirstName.Trim()} {input.LastName.Trim()}".ToUpperInvariant();if(await db.Enrollments.AnyAsync(x=>x.GroupId==invitation.Id&&x.NormalizedName==name,ct))return Results.Conflict(new{message="Заявка с таким именем уже отправлена. Обратитесь к преподавателю."});db.Enrollments.Add(new EnrollmentRequest{GroupId=invitation.Id,FirstName=input.FirstName.Trim(),LastName=input.LastName.Trim(),NormalizedName=name});try{await db.SaveChangesAsync(ct);}catch(DbUpdateException ex)when(ex.InnerException is Npgsql.PostgresException{SqlState:"23505"}){return Results.Conflict(new{message="Заявка уже отправлена."});}return Results.Ok(new{message="Заявка отправлена. Преподаватель подтвердит участие."});}).RequireRateLimiting("join");
 }
}
